24	/** The span kinds the design names: WORKFLOW root, AGENT coordinator, TOOL steps, GUARDRAIL gate. A subset of the SDK's kinds. */
25	export type SpanKind = Extract<NeatlogsSpanKind, "WORKFLOW" | "AGENT" | "TOOL" | "GUARDRAIL">;
26	
27	/** Attributes a Roster span can carry. Every field is optional; unset fields are not written. */
28	export interface SpanAttrs {
29	  setup?: string;
30	  task?: string;
31	  attempt?: number;
32	  failureCode?: FailureCode | FailureCode[];
33	  evidenceLevel?: EvidenceLevel;
34	  repo?: string;
35	  costUsd?: number;
36	}
37	
38	export type AttrValue = string | number;
39	
40	export const MAX_STRING_BYTES = 2048;
41	export const MAX_ARRAY_ITEMS = 50;
42	
43	/** Caps a value for a span: strings ≤ 2 kB, arrays ≤ 50 items (joined), objects summarised as a key count. */
44	export function capAttr(value: unknown): string | number | boolean {
45	  if (typeof value === "number" || typeof value === "boolean") return value;
46	  let text: string;
47	  if (Array.isArray(value)) {
48	    text = value
49	      .slice(0, MAX_ARRAY_ITEMS)
50	      .map((v) => (typeof v === "object" && v !== null ? "{…}" : String(v)))
51	      .join(",");
52	  } else if (value !== null && typeof value === "object") text = `{${Object.keys(value).length} keys}`;
53	  else text = String(value);
54	  return text.length > MAX_STRING_BYTES ? text.slice(0, MAX_STRING_BYTES) : text;
55	}
56	
57	/** Maps Roster's camelCase fields to the exact `roster.*` attribute names, dropping unset fields. */
58	export function toAttributes(attrs: SpanAttrs): Record<string, AttrValue> {
59	  const out: Record<string, AttrValue> = {};
60	  if (attrs.setup !== undefined) out[ATTR.setup] = attrs.setup;
61	  if (attrs.task !== undefined) out[ATTR.task] = attrs.task;
62	  if (attrs.attempt !== undefined) out[ATTR.attempt] = attrs.attempt;
63	  if (attrs.failureCode !== undefined) {
64	    out[ATTR.failureCode] = Array.isArray(attrs.failureCode) ? attrs.failureCode.join(",") : attrs.failureCode;
65	  }
66	  if (attrs.evidenceLevel !== undefined) out[ATTR.evidenceLevel] = attrs.evidenceLevel;
67	  if (attrs.repo !== undefined) out[ATTR.repo] = attrs.repo;
68	  if (attrs.costUsd !== undefined) out[ATTR.costUsd] = attrs.costUsd;
69	  for (const [k, v] of Object.entries(out)) out[k] = capAttr(v) as AttrValue;
70	  return out;
71	}
